sketch.css:
.lt{container-type:inline-size;box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:6px;padding:12px 14px;background:var(--window);color:var(--text);font:13px/1.4 "Segoe UI",system-ui,sans-serif;overflow:hidden}
.lt *{box-sizing:border-box}
.head{display:flex;justify-content:space-between;align-items:baseline;gap:10px;flex-wrap:wrap}
.titles{display:flex;align-items:baseline;gap:8px;min-width:0}
.title{font-size:14px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.period{color:var(--muted);font-size:12px;white-space:nowrap}
.total{font-size:12.5px;color:var(--muted);font-variant-numeric:tabular-nums;white-space:nowrap}
.total b{color:var(--text);font-weight:700}
.total .tpct{margin-left:6px;font-weight:700;color:var(--accent)}
.cols,.row{display:grid;grid-template-columns:minmax(80px,125px) minmax(60px,1fr) 124px 38px 62px;align-items:center;gap:8px}
.cols{padding:2px 6px;color:var(--muted);font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.03em;border-bottom:1px solid var(--border);white-space:nowrap}
.col[data-sort]{cursor:pointer;user-select:none}
.col[data-sort]:hover{color:var(--text)}
.col.sorted{color:var(--accent)}
.c-amt,.c-pct{text-align:right}
.c-amt{text-transform:none;letter-spacing:0;font-weight:500}
.c-chip{text-align:center}
.pacekey{display:inline-flex;align-items:center;gap:4px;font-weight:500;text-transform:none;letter-spacing:0}
.pacekey i{width:2px;height:10px;background:var(--text);opacity:.55;display:inline-block}
.rows{flex:1;min-height:0;overflow:auto;display:flex;flex-direction:column;gap:1px}
.row{padding:4px 6px;border-radius:6px;cursor:pointer;border:1px solid transparent}
.row:hover{background:var(--hover)}
.row.selected{background:var(--hover);border-color:var(--accent)}
.lbl{min-width:0;line-height:1.25}
.lbl .name{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.lbl .sub{color:var(--muted);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.track{position:relative;height:10px;border-radius:5px;background:var(--background)}
.planned{position:absolute;left:0;top:0;bottom:0;border-radius:5px;background:var(--border)}
.fill{position:absolute;left:0;top:0;bottom:0;border-radius:5px;background:var(--accent)}
.fill.ahead{background:var(--positive)}
.fill.behind{background:var(--negative)}
.fill.pace{background:var(--accent)}
.fill.over{background:var(--accent)}
.fill.over:after{content:"";position:absolute;top:0;bottom:0;left:var(--cap);right:0;border-radius:0 5px 5px 0;background:repeating-linear-gradient(135deg,rgba(255,255,255,.45) 0 3px,transparent 3px 6px)}
.mark{position:absolute;top:-3px;bottom:-3px;width:2px;margin-left:-1px;background:var(--text);opacity:.55;border-radius:1px}
.amt{text-align:right;font-variant-numeric:tabular-nums;font-size:12px;color:var(--muted);white-space:nowrap}
.amt b{color:var(--text);font-weight:600}
.pct{text-align:right;font-weight:600;font-variant-numeric:tabular-nums}
.chip{justify-self:center;font-size:11px;font-weight:600;padding:1px 8px;border-radius:10px;white-space:nowrap}
.chip.ahead{color:var(--positive);background:color-mix(in srgb,var(--positive) 14%,transparent)}
.chip.pace{color:var(--muted);background:var(--background)}
.chip.behind{color:var(--negative);background:color-mix(in srgb,var(--negative) 14%,transparent)}
.chip.over{color:var(--accent);background:color-mix(in srgb,var(--accent) 14%,transparent)}
.empty{color:var(--muted);font-size:12px;padding:20px 0;text-align:center}
@container (max-width:460px){
  .cols,.row{grid-template-columns:minmax(70px,110px) minmax(60px,1fr) 40px}
  .c-amt,.c-chip,.amt,.chip{display:none}
}

sketch.js:
function render(root, props, fire) {
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const unit = props.unit || '';
  const compact = v => {
    const a = Math.abs(v);
    const f = (x, s) => (x >= 100 ? x.toFixed(0) : x >= 10 ? x.toFixed(1) : x.toFixed(2)).replace(/\.?0+$/, '') + s;
    if (a >= 1e9) return (v < 0 ? '-' : '') + f(a / 1e9, 'B');
    if (a >= 1e6) return (v < 0 ? '-' : '') + f(a / 1e6, 'M');
    if (a >= 1e3) return (v < 0 ? '-' : '') + f(a / 1e3, 'K');
    return String(Math.round(v));
  };
  const pace = Math.max(0, Math.min(1, +props.paceRatio || 0));
  const tol = isNaN(+props.tolerance) ? 0.05 : Math.max(0, +props.tolerance);
  const rows = (props.rows || []).map(r => ({
    label: String(r.label == null ? '' : r.label), sub: String(r.sublabel == null ? '' : r.sublabel),
    planned: Math.max(0, +r.planned || 0), actual: Math.max(0, +r.actual || 0)
  })).filter(r => r.label !== '');
  rows.forEach(r => {
    r.ratio = r.planned > 0 ? r.actual / r.planned : 0;
    r.variance = r.actual - pace * r.planned;
    r.status = r.actual > r.planned ? 'over'
      : r.actual < pace * r.planned - tol * r.planned ? 'behind'
      : r.actual > pace * r.planned + tol * r.planned ? 'ahead' : 'pace';
  });
  const TEXT = { over: 'Over', behind: 'Behind', ahead: 'Ahead', pace: 'On pace' };

  root.querySelector('.title').textContent = props.title || 'Schedule';
  root.querySelector('.period').textContent = props.period || '';
  const tp = rows.reduce((a, r) => a + r.planned, 0), ta = rows.reduce((a, r) => a + r.actual, 0);
  root.querySelector('.total').innerHTML = '<b>' + compact(ta) + '</b> / ' + compact(tp) + (unit ? ' ' + esc(unit) : '') +
    '<span class="tpct">' + (tp > 0 ? Math.round(ta / tp * 100) : 0) + '%</span>';

  const sortBy = props.sortBy || 'none', desc = !!props.sortDescending;
  root.querySelector('.c-amt').textContent = (props.actualLabel || 'Actual') + ' / ' + (props.plannedLabel || 'Planned');
  root.querySelectorAll('.col[data-sort]').forEach(el => {
    const k = el.dataset.sort, on = k === sortBy;
    el.classList.toggle('sorted', on);
    el.textContent = (k === 'label' ? 'Name' : k === 'percent' ? '%' : 'Status') + (on ? (desc ? ' ▼' : ' ▲') : '');
    el.onclick = () => fire('sortChanged', { sortBy: k, sortDescending: on ? !desc : false });
  });
  if (sortBy !== 'none') {
    const key = { label: r => r.label.toLowerCase(), percent: r => r.ratio, variance: r => r.variance }[sortBy];
    rows.sort((a, b) => { const x = key(a), y = key(b); return (x < y ? -1 : x > y ? 1 : 0) * (desc ? -1 : 1); });
  }

  const scale = Math.max(1, rows.reduce((m, r) => Math.max(m, r.ratio), 0));
  const pct = v => (v / scale * 100).toFixed(2) + '%';
  const box = root.querySelector('.rows');
  if (!rows.length) { box.innerHTML = '<div class="empty">Nothing scheduled</div>'; return; }
  box.innerHTML = rows.map(r => {
    const fillW = Math.min(r.ratio, scale);
    return '<div class="row' + (r.label === props.selected ? ' selected' : '') + '" data-label="' + esc(r.label) + '" title="' +
      esc(r.label + ': ' + compact(r.actual) + ' of ' + compact(r.planned) + ' ' + unit + ' (' + (r.variance >= 0 ? '+' : '-') + compact(Math.abs(r.variance)) + ' vs pace)') + '">' +
      '<div class="lbl"><div class="name">' + esc(r.label) + '</div>' + (r.sub ? '<div class="sub">' + esc(r.sub) + '</div>' : '') + '</div>' +
      '<div class="track"><div class="planned" style="width:' + pct(1) + '"></div>' +
      '<div class="fill ' + r.status + '" style="width:' + pct(fillW) + ';--cap:' + (r.ratio > 1 ? (1 / r.ratio * 100).toFixed(2) + '%' : '100%') + '"></div>' +
      '<div class="mark" style="left:' + pct(pace) + '"></div></div>' +
      '<div class="amt"><b>' + compact(r.actual) + '</b> / ' + compact(r.planned) + '</div>' +
      '<div class="pct">' + Math.round(r.ratio * 100) + '%</div>' +
      '<span class="chip ' + r.status + '">' + TEXT[r.status] + '</span></div>';
  }).join('');
  box.querySelectorAll('.row').forEach(el => el.onclick = () => fire('rowSelected', { label: el.dataset.label, selected: el.dataset.label }));
}
